/* UI orchestration: all image and project data stays on this device. */
'use strict';
globalThis.SplitProjects=(()=>{
 let ready=false,suspended=false,working=false,timer,saving=false,pending=false,revision=0,lastSignature='',manualSignature='',recoveryProject=null,replacementTarget=null,replacementData=null;
 const status=text=>$('projectStatus').textContent=text;
 function capture(){const ref=reference?{id:reference.id,asset:`ref_${reference.id}`,name:reference.name}:null;const state={campaign:$('campaign').value,formats:clone(FORMATS),checked:chosenFormats(),sources:clone(sources),outputs:clone(outputs),backgroundSource:clone(backgroundSource),baseBackground,solidBackgroundChosen,reference:ref,activeId,selectedIds:selectedLayers().map(l=>l.id),view:$('editor').hidden?'grid':'edit',safeGuides:$('safeGuides').checked,exportDpi:globalThis.SplitDensity?.get()||96,blueprint:globalThis.SplitBlueprint?.state()||null,viewports:clone(viewports),baseComposition:clone(baseComposition),sequence,customSequence};const used=new Map();const use=(asset,name)=>{if(asset&&!used.has(asset))used.set(asset,{id:asset,img:images.get(asset),blob:assetFiles.get(asset),name:name||'Imagem'})};for(const source of sources)if(source.type==='image')use(source.asset,source.name);use(backgroundSource?.asset,backgroundSource?.name);for(const out of [...outputs,...(baseComposition?[baseComposition]:[])]){use(out.background?.asset,out.background?.name);for(const l of out.layers)if(l.type==='image')use(l.asset,l.name)}if(ref)used.set(ref.asset,{id:ref.asset,img:reference.img,blob:reference.file,name:reference.name});return{state,assets:[...used.values()],signature:JSON.stringify(state)};}
 function hasWork(state){return globalThis.SplitBlueprint?.isCustom()||state.sources.length||state.outputs.length||state.backgroundSource||state.reference||state.solidBackgroundChosen||state.campaign!=='Minha campanha'||JSON.stringify(state.formats)!==JSON.stringify(DEFAULT_FORMATS)||state.checked.length!==DEFAULT_FORMATS.length;}
 function changed(){if(!ready||suspended)return;const snapshot=capture();if(snapshot.signature===lastSignature)return;lastSignature=snapshot.signature;revision++;pending=true;clearTimeout(timer);if(recoveryProject){status('Há uma campanha anterior para retomar. Salve o projeto atual ou escolha uma opção acima.');return;}status(hasWork(snapshot.state)?'Atualizando recuperação neste navegador…':'Nenhuma campanha na recuperação local.');timer=setTimeout(flush,800);}
 async function flush(){if(!ready||suspended||recoveryProject)return;if(saving||drag||pan){clearTimeout(timer);timer=setTimeout(flush,500);return;}const snapshot=capture(),savedRevision=revision;saving=true;try{if(hasWork(snapshot.state)){const project=await SplitProject.encode(snapshot.state,snapshot.assets);await SplitProject.recovery('put',project);}else await SplitProject.recovery('delete');if(savedRevision===revision){pending=false;status(hasWork(snapshot.state)?`Recuperação salva neste navegador às ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}.`:'Nenhuma campanha na recuperação local.');}else{clearTimeout(timer);timer=setTimeout(flush,0)}}catch(e){status('Recuperação indisponível. Use Salvar projeto para guardar o arquivo .split.');}finally{saving=false;}}
 function setBusy(value,message){working=value;suspended=value;$('projectBusy').hidden=!value;$('projectBusyMessage').textContent=message||'Abrindo projeto…';document.querySelector('.app').inert=value;$('generationBar').inert=value;$('saveProject').disabled=value;$('openProject').disabled=value;}
 async function save(){if(working)return;SplitEditor.finishInteraction();setBusy(true,'Salvando projeto…');try{const snapshot=capture(),project=await SplitProject.encode(snapshot.state,snapshot.assets);download(new Blob([JSON.stringify(project)],{type:'application/vnd.split.project+json'}),`${safeName()}.split`);manualSignature=snapshot.signature;toast('Projeto salvo em .split, com imagens e ajustes de todos os formatos.');}catch(e){toast(`Não foi possível salvar o projeto: ${e.message}`)}finally{setBusy(false);changed();}}
 function maxSequence(project){return Math.max(sequence,project.sequence,...[...project.sources,...project.outputs.flatMap(o=>o.layers),...(project.baseComposition?.layers||[]),...(project.reference?[project.reference]:[])].flatMap(l=>[l.id,l.groupId]).map(id=>/^e\d+$/.test(id)?Number(id.slice(1)):0));}
 function apply(decoded){const {project,assets}=decoded;checkpoint();sequence=maxSequence(project);const remap=new Map();for(const [old,value]of assets){const newId=uid();remap.set(old,newId);images.set(newId,value.img);}const bg=value=>value?{...value,asset:remap.get(value.asset)}:null;const copyLayer=l=>l.type==='image'?{...l,asset:remap.get(l.asset)}:{...l};sources=project.sources.map(copyLayer);outputs=project.outputs.map(out=>({...out,background:bg(out.background),layers:out.layers.map(copyLayer)}));baseComposition=project.baseComposition?{...project.baseComposition,background:bg(project.baseComposition.background),layers:project.baseComposition.layers.map(copyLayer)}:null;backgroundSource=bg(project.backgroundSource);reference=project.reference?{...assets.get(project.reference.asset),id:project.reference.id}:null;baseBackground=project.baseBackground;solidBackgroundChosen=project.solidBackgroundChosen;customSequence=Math.max(customSequence,project.customSequence,...project.formats.filter(f=>/^custom-\d+$/.test(f.id)).map(f=>Number(f.id.slice(7))));FORMATS.splice(0,FORMATS.length,...project.formats);activeId=project.activeId;viewports=clone(project.viewports);selectedIds=project.selectedIds.filter(id=>current()?.layers.some(l=>l.id===id));selectedId=selectedIds.at(-1)||null;alignmentGuides=[];$('campaign').value=project.campaign;$('safeGuides').checked=project.safeGuides;globalThis.SplitDensity?.set(project.exportDpi,{notify:false});globalThis.SplitBlueprint?.restore(project.blueprint);formatOptions(project.checked);refresh();setView(project.view);recoveryProject=null;$('recoveryBanner').hidden=true;lastSignature='';manualSignature='';}
 async function openValue(value,recovered=false){if(working)return;setBusy(true,recovered?'Recuperando campanha…':'Abrindo projeto…');try{const decoded=await SplitProject.decode(value);await ensureFonts();SplitEditor.finishInteraction();apply(decoded);toast(recovered?'Campanha recuperada com imagens e ajustes.':'Projeto aberto. Imagens, formatos e ajustes recuperados.',true);return true;}catch(e){toast(`Não foi possível abrir o projeto: ${e.message}`);return false;}finally{setBusy(false);changed();}}
 async function openFile(file){if(!file)return;if(file.size>512*1024*1024){toast('O arquivo de projeto deve ter até 512 MB.');return;}try{await openValue(await file.text());}catch(e){toast('Não foi possível ler este arquivo de projeto.');}}
 function chooseReplacement(role,id){replacementTarget={role,id};$('replaceFile').click();}
 async function prepareReplacement(file){if(!file||!replacementTarget)return;try{const data=await readImage(file);if(!data)return;const target=replacementTarget.role==='background'?backgroundSource:sources.find(s=>s.id===replacementTarget.id&&s.type==='image');if(!target){toast('Esta imagem não está mais na campanha.');return;}replacementData=data;const original=images.get(target.asset);$('replaceName').textContent=`${target.name} → ${data.name}`;$('replaceDimensions').textContent=`Atual: ${original.width} × ${original.height} px · Nova: ${data.img.width} × ${data.img.height} px`;$('replaceDialog').querySelector('input[value="keep"]').checked=true;$('replaceDialog').querySelector('.replacement-options').hidden=replacementTarget.role==='background';$('replaceDialog').showModal();}catch(e){toast(e.message)}}
 function cancelReplacement(){if(replacementData?.url?.startsWith('blob:'))URL.revokeObjectURL(replacementData.url);replacementData=null;replacementTarget=null;$('replaceDialog').close();}
 function replace(mode='keep'){const target=replacementTarget,data=replacementData;if(!target||!data)return;const source=target.role==='background'?backgroundSource:sources.find(s=>s.id===target.id&&s.type==='image');if(!source){cancelReplacement();return;}checkpoint();const oldAsset=source.asset,newAsset=uid();images.set(newAsset,data.img);if(data.file)assetFiles.set(newAsset,data.file);const aspect=data.img.width/data.img.height,label={text:'Texto (imagem)',offer:'Oferta',logo:'Logo',cta:'Botão'}[source.role];const name=target.role==='background'?data.name:label?`${label} · ${data.name}`:data.name;source.asset=newAsset;source.name=name;for(const out of outputs){if(target.role==='background'){if(out.background?.asset===oldAsset){out.background.asset=newAsset;out.background.name=name;}}else for(const l of out.layers)if(l.id===target.id){l.asset=newAsset;l.name=name;if(mode==='adapt'){const center=l.y+l.h/2;l.h=l.w*out.w/(aspect*out.h);l.y=center-l.h/2;}l.aspect=aspect;l.manualLayout=true;}}
  replacementData=null;replacementTarget=null;$('replaceDialog').close();refresh();toast('Imagem substituída nos formatos. Os demais elementos mantiveram seus ajustes.',true);}
 async function discard(){if(working)return;try{await SplitProject.recovery('delete');recoveryProject=null;$('recoveryBanner').hidden=true;lastSignature='';changed();toast('Cópia anterior removida deste navegador.');}catch(e){toast('Não foi possível remover a cópia local. Tente novamente.');}}
 async function init(){const initialSignature=capture().signature;try{const stored=await SplitProject.recovery('get');if(stored){recoveryProject=stored;$('recoveryName').textContent=`${stored.campaign||'Campanha'} · ${stored.savedAt?new Date(stored.savedAt).toLocaleString('pt-BR'):''}`;$('recoveryBanner').hidden=false;status('Uma campanha está disponível para recuperação neste navegador.');}}catch(e){status('Recuperação indisponível. Use Salvar projeto para guardar o arquivo .split.');}ready=true;lastSignature=initialSignature;changed();}
 $('saveProject').onclick=save;$('openProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=ev=>{const file=ev.target.files[0];ev.target.value='';openFile(file)};$('campaign').oninput=changed;$('restoreProject').onclick=()=>openValue(recoveryProject,true);$('discardRecovery').onclick=discard;$('replaceFile').onchange=ev=>{const file=ev.target.files[0];ev.target.value='';prepareReplacement(file)};$('cancelReplace').onclick=cancelReplacement;$('replaceDialog').onclose=()=>{if(replacementData)cancelReplacement()};$('confirmReplace').onclick=()=>replace($('replaceDialog').querySelector('input[name="replacementFit"]:checked')?.value||'keep');window.addEventListener('pagehide',()=>{if(pending)flush()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&pending)flush()});
 const initialized=init();return{changed,flush,capture,save,openFile,openValue,chooseReplacement,prepareReplacement,replace,initialized,busy:()=>working,needsUnloadWarning:()=>pending&&capture().signature!==manualSignature};
})();
